    private void siapkanFormAkunYangJelas() {
        // Layout generated by NetBeans contains fixed 305px offsets that clip on narrow screens.
        // The same original labels/fields remain, now in a clean vertical flow.
        java.awt.Component[] fields=pnlFields.getComponents();
        pnlFields.removeAll();
        pnlFields.setLayout(new java.awt.GridLayout(0,1,0,4));
        pnlFields.setPreferredSize(new java.awt.Dimension(295,284));
        for (java.awt.Component field : fields) {
            pnlFields.add(field);
            if (field == input3) {
                javax.swing.JCheckBox reveal=new javax.swing.JCheckBox("Tampilkan kata sandi");
                reveal.setOpaque(false);
                reveal.setForeground(new java.awt.Color(27,42,92));
                reveal.setFont(new java.awt.Font("Segoe UI",java.awt.Font.PLAIN,12));
                final char echo=input3.getEchoChar();
                reveal.addActionListener(e->input3.setEchoChar(reveal.isSelected()?(char)0:echo));
                pnlFields.add(reveal);
            }
        }
        lblField3.setText("Kata sandi (minimal 5 karakter)");
        pnlActions.removeAll();
        pnlActions.setLayout(new java.awt.FlowLayout(java.awt.FlowLayout.LEFT,7,6));
        btnAksi1.setPreferredSize(new java.awt.Dimension(276,35));
        btnAksi2.setPreferredSize(new java.awt.Dimension(276,35));
        btnAksi3.setPreferredSize(new java.awt.Dimension(276,35));
        pnlActions.add(btnAksi1); pnlActions.add(btnAksi2); pnlActions.add(btnAksi3);
        setPreferredSize(new java.awt.Dimension(1030,700));
    }
    /** Admin & Staff menggunakan daftar divisi yang sesuai database; area Supervisor tetap editable. */
    private void perbaruiPilihanDivisi() {
        String sebelumnya = input5.getSelectedItem() == null ? "" : input5.getSelectedItem().toString();
        String role = String.valueOf(input4.getSelectedItem());
        input5.removeAllItems();
        String[] pilihan = "Admin".equals(role)
                ? new String[]{"administrasi", "produksi", "logistik"}
                : "Staff".equals(role) ? new String[]{"Produksi", "Pengemasan", "Gudang"}
                : new String[]{"Lini Produksi"};
        for (String p : pilihan) input5.addItem(p);
        input5.setEditable("Supervisor".equals(role));
        for (String p : pilihan) if (p.equalsIgnoreCase(sebelumnya)) {
            input5.setSelectedItem(p); return;
        }
    }

    @Override public javax.swing.JTable tabel() { return tblData; }
    @Override public javax.swing.JTextField pencarian() { return txtCari; }
    @Override public javax.swing.JButton tombolCari() { return btnCari; }
    @Override public javax.swing.JButton tombolSegarkan() { return btnSegarkan; }
    @Override public void pesan(String s) { lblStatus.setText(s); }
    @Override public void tampilkanForm(boolean show) { pnlLeft.setVisible(show); }
    @Override public javax.swing.JButton tombol(int i) {
        switch (i) {
            case 0: return btnAksi1;
            case 1: return btnAksi2;
            case 2: return btnAksi3;
            default: return null;
        }
    }
    @Override public javax.swing.JComponent masukan(int i) {
        switch (i) {
            case 0: return input1;
            case 1: return input2;
            case 2: return input3;
            case 3: return input4;
            case 4: return input5;
            default: return null;
        }
    }

